-- 0032_dashboard_system_seed.sql seeded "rapports-architecture"'s four
-- metrics panels pointing at architecture-neo4j (Cypher). Following the
-- precedent of the prior backfills in this series, this migration points
-- the dashboard's latest revision (3) at the native Postgres datasource:
-- three panels are plain counts over elements/relationships/views scoped by
-- organization, and "couches" reproduces getLayer's classification
-- (packages/db-neo4j/src/layer.ts) as an inline CASE expression to count
-- distinct ArchiMate layers, the same approach used by
-- 0037_rapports_application_datasource_postgres.sql.
UPDATE "dashboard_revisions" AS dr
SET "definition" = $def$
{"id": "rapports-architecture", "title": "Rapports d’Architecture", "description": "Vue d’ensemble du modèle ArchiMate courant.", "category": "Architecture", "schemaVersion": 2, "parameters": [], "panels": [{"id": "elements", "panel": {"title": "Éléments", "description": "Nombre total d’éléments ArchiMate affiché par le plugin d’exemple.", "resultType": "metrics", "parameters": [], "visualization": {"type": "core/metric", "max": 1000}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT count(*)::integer AS count\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId"}}, "layout": {"x": 0, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "relations", "panel": {"title": "Relations", "description": "Nombre total de relations ArchiMate.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT count(*)::integer AS count\nFROM relationships r\nJOIN workspaces w ON w.id = r.workspace_id\nWHERE w.organization_id = $organizationId"}}, "layout": {"x": 3, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "vues", "panel": {"title": "Vues", "description": "Nombre total de vues ArchiMate.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT count(*)::integer AS count\nFROM views v\nJOIN workspaces w ON w.id = v.workspace_id\nWHERE w.organization_id = $organizationId"}}, "layout": {"x": 6, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "couches", "panel": {"title": "Couches ArchiMate", "description": "Nombre de couches présentes dans le modèle.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT count(DISTINCT (CASE\n    WHEN e.type LIKE 'Business%' OR e.type IN ('Contract', 'Representation', 'Product') THEN 'Business'\n    WHEN e.type LIKE 'Application%' OR e.type = 'DataObject' THEN 'Application'\n    WHEN e.type LIKE 'Technology%' OR e.type IN ('Node', 'Device', 'SystemSoftware', 'Path', 'CommunicationNetwork', 'Artifact') THEN 'Technology'\n    WHEN e.type IN ('Equipment', 'Facility', 'DistributionNetwork', 'Material') THEN 'Physical'\n    WHEN e.type IN ('Stakeholder', 'Driver', 'Assessment', 'Goal', 'Outcome', 'Principle', 'Requirement', 'Constraint', 'Meaning', 'Value') THEN 'Motivation'\n    WHEN e.type IN ('Resource', 'Capability', 'CourseOfAction', 'ValueStream') THEN 'Strategy'\n    WHEN e.type IN ('WorkPackage', 'Deliverable', 'ImplementationEvent', 'Plateau', 'Gap') THEN 'Implementation'\n    ELSE 'Composite'\n  END))::integer AS count\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId"}}, "layout": {"x": 9, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}], "createdAt": "2026-08-07T16:30:00.000Z", "updatedAt": "2026-08-17T03:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "system"}
$def$::jsonb
FROM "dashboards" AS dd
WHERE dr."dashboard_id" = dd."id"
  AND dd."dashboard_id" = 'rapports-architecture'
  AND dd."workspace_id" IS NULL
  AND dr."revision" = dd."latest_revision";
